<script setup lang="ts">
const route = useRoute()
const id = String(route.params.moduleId)
const { $api } = useNuxtApp()
const { data: pkg, error } = await useAsyncData(`package-${id}`, () => $api.package(id))
if (error.value || !pkg.value) throw createError({ statusCode: 404, statusMessage: 'Package not found' })
const latest = computed(() => pkg.value!.versions[0]!)
usePageSeo(`${pkg.value.name} · Open City Planner Packages`, pkg.value.description || `Registry details for ${pkg.value.name}.`, `/packages/${id}`)
</script>

<template><div v-if="pkg" class="container-shell py-7"><nav class="text-xs text-slate-500" aria-label="Breadcrumb"><NuxtLink to="/packages" class="hover:text-link-700">Packages</NuxtLink><span class="mx-2" aria-hidden="true">/</span><span class="font-mono">{{ pkg.id }}</span></nav><header class="mt-6 border-b border-slate-200 pb-7"><div class="flex flex-col gap-6 md:flex-row md:items-start"><PackageIcon :name="pkg.name" /><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-3"><h1 class="page-title">{{ pkg.name }}</h1><PackageBadge :value="latest.channel" /></div><div class="mt-2 flex items-center gap-2"><CopyValue :value="pkg.id" label="package ID" truncate /></div><p class="mt-4 max-w-3xl text-base leading-7 text-slate-600">{{ pkg.description }}</p><div class="mt-4"><PublisherBadge :publisher="pkg.publisher" :classification="pkg.classification" /></div></div><VersionSelector :module-id="pkg.id" :versions="pkg.versions" :selected="latest.version" /></div></header><nav class="flex gap-6 overflow-x-auto border-b border-slate-200 text-sm font-semibold" aria-label="Package sections"><a v-for="section in ['Overview','Versions','Compatibility','Provenance']" :key="section" :href="`#${section.toLowerCase()}`" class="border-b-2 border-transparent px-0.5 py-3.5 hover:border-brand-500 hover:text-brand-700">{{ section }}</a><a v-if="pkg.documentation_url" :href="pkg.documentation_url" class="border-b-2 border-transparent px-0.5 py-3.5 hover:border-brand-500">Documentation ↗</a><a :href="pkg.source_repository" class="border-b-2 border-transparent px-0.5 py-3.5 hover:border-brand-500">Source ↗</a></nav><div class="mt-7 grid gap-8 lg:grid-cols-[minmax(0,7fr)_minmax(250px,3fr)]"><div class="grid gap-9"><section id="overview"><p class="eyebrow">Overview</p><h2 class="mt-2 text-2xl font-bold">{{ pkg.name }}</h2><p class="mt-4 max-w-3xl leading-7 text-slate-700">{{ pkg.description }}</p><div class="mt-6 flex flex-wrap gap-2"><PackageBadge :value="pkg.classification" /><PackageBadge :value="latest.channel" /><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold">Immutable .ocp</span></div></section><section id="versions"><div class="flex items-baseline justify-between"><h2 class="text-xl font-bold">Versions</h2><span class="text-xs text-slate-500">{{ pkg.versions.length }} {{ pkg.versions.length === 1 ? 'release' : 'releases' }}</span></div><ul class="mt-3 border-y border-slate-200"><li v-for="release in pkg.versions" :key="release.version" class="grid grid-cols-[1fr_auto] items-center gap-4 border-b border-slate-100 py-4 last:border-0"><div><NuxtLink :to="`/packages/${pkg.id}/${release.version}`" class="font-mono font-bold text-link-700">{{ release.version }}</NuxtLink><p class="mt-1 text-xs text-slate-500">Bundle v{{ release.bundle_format_version }} · {{ release.source_tag || 'No source tag' }}</p></div><PackageBadge :value="release.channel" /></li></ul></section><section id="compatibility"><h2 class="text-xl font-bold">Compatibility</h2><dl class="mt-3 border-y border-slate-200"><div class="metadata-row"><dt class="text-slate-500">Open City Planner host</dt><dd class="font-mono text-sm">{{ latest.requires.host }}</dd></div><div class="metadata-row"><dt class="text-slate-500">Module SDK</dt><dd class="font-mono text-sm">{{ latest.requires.sdk }}</dd></div><div class="metadata-row"><dt class="text-slate-500">Module dependencies</dt><dd class="text-sm">{{ Object.keys(latest.requires.modules).length ? `${Object.keys(latest.requires.modules).length} declared` : 'None declared' }}</dd></div></dl></section><ProvenancePanel id="provenance" :pkg="pkg" :release="latest" /></div><PackageMetadataRail :pkg="pkg" :release="latest" /></div></div></template>
